import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

bn_scale_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void bn_scale_kernel(
    const float* __restrict__ input,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    float eps,
    float scale_factor)
{
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * C * H * W;
    if (index >= total_size) {
        return;
    }

    int spatial_size = H * W;
    int n = index / (C * spatial_size);
    int c = (index / spatial_size) % C;
    float x_val = input[index];
    float mean_c = running_mean[c];
    float var_c = running_var[c];
    float w_c = weight[c];
    float b_c = bias[c];

    float norm_x = (x_val - mean_c) / sqrtf(var_c + eps);
    float y = norm_x * w_c + b_c;
    output[index] = y * scale_factor;
}

torch::Tensor bn_scale_forward(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps,
    float scale_factor
) {
    const auto N = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);

    auto output = torch::empty_like(input);
    int total_size = N * C * H * W;

    const int block_size = 256;
    const int grid_size = (total_size + block_size - 1) / block_size;

    bn_scale_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        eps,
        scale_factor
    );

    return output;
}
"""

bn_scale_cpp_source = r"""
torch::Tensor bn_scale_forward(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps,
    float scale_factor
);
"""

bn_scale = load_inline(
    name="bn_scale",
    cpp_sources=bn_scale_cpp_source,
    cuda_sources=bn_scale_source,
    functions=["bn_scale_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses Batch Normalization and scaling into a custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        self.bn_scale = bn_scale

    def forward(self, x):
        x = self.conv(x)
        x = self.bn_scale.bn_scale_forward(
            x,
            self.bn.running_mean,
            self.bn.running_var,
            self.bn.weight,
            self.bn.bias,
            self.bn.eps,
            self.scaling_factor
        )
        return x
